INSERT INTO dc_follower_skill (follower_id, tier, d3_level, skill_id, name, cooldown_seconds, scales_with, requires_weapon, text) VALUES
(1,1,5,'heal','Heal',30,'strength','','Cooldown: 30 seconds / Heals you and the Templar for 193017 Life based on the Templar''s Strength.'),
(1,1,5,'intervene','Intervene',10,'strength','','Cooldown: 10 seconds / Taunt enemies within 10 yards of you for 3.00 seconds when you are hit, based on the Templar''s Strength.'),
(1,2,10,'loyalty','Loyalty',NULL,'strength','','Regenerates 6432 Life per second for you and the Templar based on the Templar''s Strength.'),
(1,2,10,'intimidate','Intimidate',NULL,'strength','','Enemies that hit or are hit by the Templar are slowed by 80% for 3.00 seconds based on the Templar''s Strength.'),
(1,3,15,'charge','Charge',10,'strength','','Cooldown: 10 seconds / Charges a target, dealing 280% weapon damage and stunning all enemies within 8 yards for 3.00 seconds based on the Templar''s Strength.'),
(1,3,15,'onslaught','Onslaught',20,'strength','','Cooldown: 20 seconds / Delivers a massive blow to an enemy for 800% weapon damage and causes the target and nearby enemies to take 10% increased damage for 3.00 seconds based on the Templar''s Strength.'),
(1,4,20,'inspire','Inspire',NULL,'','','Increases your resource generation. / Mana: 7 per second. / Hatred: 1 per second. / Wrath: 1.1 per second. / Arcane Power: 1.4 per second. / Fury: 10% generated. / Spirit: 10% generated. / Essence: 10% generated.'),
(1,4,20,'guardian','Guardian',120,'strength','','Cooldown: 120 seconds / When you take fatal damage, the Templar rushes to your aid, knocking back enemies within 15 yards, healing you for 15.00% Life based on the Templar''s Strength, and shielding you from all damage for 5 seconds.'),
(2,1,5,'crippling-shot','Crippling Shot',4,'dexterity','Bow','Cooldown: 4 seconds / Ranged attack that deals 140% weapon damage and slows enemies hit by 80% for 3.00 seconds based on the Scoundrel''s Dexterity. Requires Bow'),
(2,1,5,'powered-shot','Powered Shot',8,'dexterity','Bow','Cooldown: 8 seconds / Ranged attack that explodes on impact, dealing 120% weapon damage as Arcane to enemies within 10 yards and has a 100% chance to Stun enemies for 3.00 seconds based on the Scoundrel''s Dexterity. Requires Bow'),
(2,2,10,'hysteria','Hysteria',NULL,'dexterity','','Whenever you or the Scoundrel land a Critical Hit, you both will go into hysterics, increasing all damage done by 3% for 3.00 seconds based on the Scoundrel''s Dexterity.'),
(2,2,10,'anatomy','Anatomy',NULL,'dexterity','','Increases Critical Hit Chance by 1.80% for you and the Scoundrel based on the Scoundrel''s Dexterity.'),
(2,3,15,'piercing-shot','Piercing Shot',20,'dexterity','Bow','Cooldown: 20 seconds / Ranged attack that pierces that deals 500% weapon damage and increases damage done to enemies by 10% for 3.00 seconds based on the Scoundrel''s Dexterity. Requires Bow'),
(2,3,15,'multishot','Multishot',8,'dexterity','Bow','Cooldown: 8 seconds / Active: The Scoundrel will shoot 3 bolts, each dealing 110% weapon damage. / Passive: The Scoundrel''s special attacks have a 49.99% chance to fire 3 bolts based on the Scoundrel''s Dexterity. Requires Bow'),
(2,4,20,'vanish','Vanish',120,'dexterity','','Cooldown: 120 seconds / When you take fatal damage, the Scoundrel conceals you from enemies for 3.00 seconds based on the Scoundrel''s Dexterity, allowing you to escape your death.'),
(2,4,20,'nights-veil','Night''s Veil',30,'dexterity','','Cooldown: 30 seconds / The Scoundrel launches a cloud that covers a 20 yard area and lasts 2.00 seconds based on the Scoundrel''s Dexterity. All attacks against enemies that are inside the cloud will be critical hits.'),
(3,1,15,'charm','Charm',18,'','','Cooldown: 18 seconds / Charms an enemy to fight for you for 8 seconds.'),
(3,1,15,'temporal-pulse','Temporal Pulse',4,'intelligence','','Cooldown: 4 seconds / The Enchantress casts a guided orb that deals 150% weapon damage as Arcane to enemies within 15 yards and slows them by 80% for 3.00 seconds based on the Enchantress''s Intelligence.'),
(3,2,20,'amplification','Amplification',NULL,'intelligence','','Increases your static elemental damage bonuses by 5.00% based on the Enchantress''s Intelligence.'),
(3,2,20,'prophetic-harmony','Prophetic Harmony',NULL,'intelligence','','Reduces your Skills'' Cooldowns by 5.00% based on the Enchantress''s Intelligence.'),
(3,3,25,'powered-shield','Powered Shield',NULL,'intelligence','','Reduces damage by 6% from ranged attacks, increases Armor by 3% and slows melee attackers by 60% for 3.00 seconds for you and the Enchantress based on her Intelligence.'),
(3,3,25,'erosion','Erosion',20,'intelligence','','Cooldown: 20 seconds / Conjures a pool of energy that deals 330% weapon damage as Arcane over 5.00 seconds based on the Enchantress''s Intelligence. Affected enemies will also take 10% increased damage.'),
(3,4,30,'focused-mind','Focused Mind',NULL,'intelligence','','A 40 yard aura that increases attack speed for you and the Enchantress by 3.00% based on the Enchantress''s Intelligence.'),
(3,4,30,'fates-lapse','Fate''s Lapse',120,'intelligence','','Cooldown: 120 seconds / When you take fatal damage, the Enchantress empowers you to move through time, slowing enemies'' movement, attack speed, and projectiles by 80% for 3.00 seconds to avoid death based on the Enchantress''s Intelligence.');
